"use strict";(globalThis.webpackChunkweb||=[]).push([[6387],{76387(e){e.exports=JSON.parse('{"group":"statements","count":107,"entries":{"CATNAME":{"help":"Logically combines two or more catalogs into one by associating them with a catref \\n(a shortcut name); clears one or all catrefs; lists the concatenated catalogs in \\none concatenation or in all concatenations.\\n\\nSyntax:\\n\\n(1) CATNAME <libref.> catref\\n    < (libref-1.catalog-1 <(ACCESS=READONLY)> \\n    <...libref-n.catalog-n <(ACCESS=READONLY)>)> ;\\n\\n(2) CATNAME <libref.> catref CLEAR | _ALL_ CLEAR;\\n\\n(3) CATNAME <libref.> catref LIST | _ALL_ LIST; "},"FILENAME":{"help":"Associates a SAS fileref with an external file or an output device;\\ndisassociates a fileref and external file; lists attributes of external files.\\n\\nSyntax:\\n\\n(1) FILENAME fileref <device-type> \'external-file\' <ENCODING=\'encoding-value\'>\\n    <options><operating-environment-options>;\\n\\n(2) FILENAME fileref <device-type><options> <operating-environment-options>;\\n\\n(3) FILENAME fileref CLEAR | _ALL_ CLEAR;\\n\\n(4) FILENAME fileref LIST | _ALL_ LIST; \\n\\n(5) FILENAME fileref CATALOG \'catalog\' <catalog-options>; \\n\\n(6) FILENAME fileref CLIPBRD <BUFFER=paste-buffer-name>; \\n\\n(7) FILENAME fileref EMAIL <\'address\' ><email-options>; \\n\\n(8) FILENAME fileref FTP \'external-file\' <ftp-options>; \\n\\n(9) FILENAME fileref SFTP \'external-file\' <sftp-options>; \\n\\n(10) FILENAME fileref SOCKET \'hostname:portno\' <tcpip-options>;  \\n\\n(11) FILENAME fileref SOCKET \':portno\' SERVER <tcpip-options>;  \\n\\n(12) FILENAME fileref URL \'external-file\' <url-options>; \\n\\n(13) FILENAME filref WEBDAV \'external-file\' <webdav-options>; \\n\\n(14) FILENAME fileref DDE \'DDE-triplet\' <DDE-options>;"},"LIBNAME":{"help":"Associates or disassociates a SAS data library with a libref (a shortcut name); \\nclears one or all librefs; lists the characteristics of a SAS data library; \\nconcatenates SAS data libraries; implicitly concatenates SAS catalogs.\\n\\nSyntax:\\n\\n(1) LIBNAME libref <engine> \'SAS-data-library\' < options > <engine/host-options>;\\n\\n(2) LIBNAME libref CLEAR | _ALL_ CLEAR;\\n\\n(3) LIBNAME libref LIST | _ALL_ LIST;\\n\\n(4) LIBNAME libref <engine> (library-specification-1 <... library-specification-n>) < options >; \\n\\n(5) LIBNAME libref INFOMAPS MAPPATH=\\"location\\" <options>; \\n\\n(6) LIBNAME libref XML <\'SAS-library | XML-document-path\' > <basic-options> <NLS-options> <advanced-options>; \\n\\n(7) LIBNAME libref SASEDOC \'path\' <sasedoc-engine-option> <options>;\\n\\n(8) LIBNAME libref <engine-name> <physical-file-name> <SAS/ACCESS-engine-connection-options> \\n      <SAS/ACCESS-libname-options>;"},"PAGE":{"help":"Skips to a new page in the SAS log.\\n\\nSyntax: PAGE; "},"SKIP":{"help":"Creates a blank line in the SAS log.\\n\\nSyntax: SKIP <n>; \\n\\nwhere n specifies the number of blank lines that you want to create in the log."},"FOOTNOTE":{"help":"Syntax: FOOTNOTE<n ><ods-format-options> <\'text\' | \\"text\\" >; \\n    \\nWrites up to 10 lines of text at the bottom of the procedure or DATA step output.","attributes":"ForceColor|Global|NumericSuffix"},"TITLE":{"help":"Syntax: TITLE<n> <ods-format-options><\'text\' | \\"text\\">; \\n    \\nSpecifies title lines for SAS output.","attributes":"ForceColor|Global|NumericSuffix"},"ENDSAS":{"help":"Terminates a SAS job or session after the current DATA or PROC step executes.\\n    \\nSyntax: ENDSAS; "},"%INCLUDE":{"help":"Brings a SAS programming statement, data lines, or both, into a current SAS program.\\n\\nSyntax: %INCLUDE source(s) </<SOURCE2> <S2=length> <operating-environment-options>>; "},"%INC":{"help":"Brings a SAS programming statement, data lines, or both, into a current SAS program.\\n\\nSyntax: %INCLUDE source(s) </<SOURCE2> <S2=length> <operating-environment-options>>; "},"LOCK":{"help":"Syntax: LOCK libref<.member-name<.member-type | .entry-name.entry-type>> <LIST | QUERY | SHOW | CLEAR | NOMSG> ; \\n    \\nAcquires and releases an exclusive lock on an existing SAS file."},"OPTIONS":{"help":"Syntax: OPTIONS <options-list>; \\n    \\nChanges the value of one or more SAS system options."},"OPTION":{"help":"Syntax: OPTIONS <options-list>; \\n    \\nChanges the value of one or more SAS system options."},"GOPTIONS":{"help":"Syntax: GOPTIONS <options-list>; \\n    \\nTemporarily sets default values for many graphics attributes and device parameters \\nused by SAS/GRAPH procedures."},"GOPTION":{"help":"Syntax: GOPTIONS <options-list>; \\n    \\nTemporarily sets default values for many graphics attributes and device parameters \\nused by SAS/GRAPH procedures."},"RUN":{"help":"[Syntax: RUN <CANCEL>;] \\n    \\nExecutes the previously entered SAS statements."},"RUN CANCEL":{"help":"Syntax: RUN CANCEL;\\n    \\nTerminates the current step without executing it. SAS prints a message that indicates that the step was not executed. \\n\\nCAUTION:\\n  The CANCEL option does not prevent execution of a DATA step that contains a DATALINES or DATALINES4 statement. \\nCAUTION:\\n  The CANCEL option has no effect when you use the KILL option with PROC DATASETS.","states":"RUN"},"%RUN":{"help":"Syntax: %RUN;\\n    \\nEnds source statements following a %INCLUDE * statement."},"%LIST":{"help":"Displays lines that are entered in the current session. \\n    \\nSyntax: %LIST<n <:m | - m>>; \\n\\nwhere\\n\\nn - means display line n.\\n\\nn-m - means display lines n through m; can be written as n:m"},"QUIT":{"help":"Quit from the current SAS session.","states":"QUIT"},"SASFILE":{"help":"Syntax: SASFILE <libref.>member-name<.member-type> <(password-option(s))> OPEN | LOAD | CLOSE ; \\n    \\nOpens a SAS data set and allocates enough buffers to hold the entire file in memory. \\n\\npassword-option(s)\\n  specifies one or more of the following password options:\\n    ENCRYPTKEY=key-value\\n      enables the SASFILE statement to open an AES-encrypted SAS data file. If a SAS data file is encrypted \\n      with the AES (Advanced Encryption Standard) algorithm, a key value is assigned to the file and must be \\n      specified in order to access the file. The key value can be up to 64 bytes long.\\n    \\n    READ=password\\n      enables the SASFILE statement to open a read-protected file. The password must be a valid SAS name.\\n    WRITE=password\\n      enables the SASFILE statement to use the WRITE password to open a file that is both read-protected \\n      and write-protected. The password must be a valid SAS name.\\n    ALTER=password\\n      enables the SASFILE statement to use the ALTER password to open a file that is both read-protected \\n      and alter-protected. The password must be a valid SAS name.\\n    PW=password\\n      enables the SASFILE statement to use the password to open a file that is assigned for all levels of \\n      protection. The password must be a valid SAS name."},"PROC":{"help":"Syntax: PROC procedure-name <options>;\\n\\nAlias: PROCEDURE\\n\\nBegins a PROC step. The PROC step consists of a group of SAS statements that call and execute\\na procedure, usually with a SAS data set as input.","states":"PROC"},"PROCEDURE":{"help":"Syntax: PROCEDURE procedure-name <options>;\\n\\nAlias: PROC\\n\\nBegins a PROC step. The PROC step consists of a group of SAS statements that call and execute\\na procedure, usually with a SAS data set as input.","states":"PROC"},"DATA":{"help":"Begins a DATA step and provides names for any output SAS data sets, views, or programs. \\n    \\nSyntax: \\n    \\n(1) DATA <data-set-name-1 <(data-set-options-1)>> \\n      <... data-set-name-n <(data-set-options-n)>> </ <DEBUG> <NESTING> <STACK = stack-size>> <NOLIST>;  \\n\\n(2) DATA _NULL_ </ <DEBUG> <NESTING> <STACK = stack-size>> <NOLIST>;  \\n\\n(3) DATA view-name <data-set-name-1 <(data-set-options-1)>> \\n      <... data-set-name-n <(data-set-options-n)>> / \\n      VIEW=view-name <(<password-option><SOURCE=source-option>)> <NESTING> <NOLIST>;  \\n\\n(4) DATA data-set-name / PGM=program-name <(<password-option><SOURCE=source-option>)> <NESTING> <NOLIST>;  \\n\\n(5) DATA VIEW=view-name <(password-option)> <NOLIST>;  \\n      DESCRIBE;  \\n \\n(6) DATA PGM=program-name <(password-option)> <NOLIST>;  \\n      <DESCRIBE;>  \\n      <REDIRECT INPUT | OUTPUT old-name-1 = new-name-1<... old-name-n = new-name-n>;>  \\n      <EXECUTE;>","attributes":"ForceColor|NumericSuffix","states":"DATA"},"ODS":{"help":"ODS statements provide great flexibility in generating, storing, and reproducing SAS \\nprocedure and DATA step output."},"CHECKPOINT EXECUTE_ALWAYS":{"help":"Indicates to execute the DATA step or PROC step that immediately follows without considering\\nthe checkpoint-restart data."},"SYSECHO":{"help":"Fires a global statement complete event and passes a text string back to the IOM client."},"DM":{"help":"Submits SAS Program Editor, Log, Procedure Output or text editor commands as SAS statements."},"SYMBOL":{"help":"Syntax: SYMBOL<1...255> <COLOR=symbol-color|_style_> \\n  <MODE=EXCLUDE | INCLUDE> <REPEAT=number-of-times> \\n  <STEP=distance<units>> <appearance-option(s)> \\n  <interpolation-option> <SINGULAR=n>; \\n    \\nDefines the characteristics of symbols that display the data plotted by a PLOT \\nstatement used by PROC GBARLINE, PROC GCONTOUR, and PROC GPLOT. \\n\\nUsed by: GBARLINE, GCONTOUR, GPLOT procedures","attributes":"ForceColor|Global|NumericSuffix"},"AXIS":{"help":"Syntax: AXIS<1...99> <options>; \\n    \\nControls the location, values, and appearance of the axes in plots and charts. \\n\\nUsed by: GBARLINE, GCHART, GCONTOUR, GRADAR, G3D procedures"},"LEGEND":{"help":"Syntax: LEGEND<1...99> <options>; \\n    \\nControls the location and appearance of legends on two-dimensional plots, contour \\nplots, maps, and charts. \\n\\nUsed by: GAREABAR, GCHART, GBARLINE, GCONTOUR, GMAP, GPLOT procedures","attributes":"ForceColor|NumericSuffix"},"PATTERN":{"help":"Syntax: PATTERN<1...255> <COLOR=pattern-color |_style_> \\n  <REPEAT=number-of-times> \\n  <VALUE=bar/block-pattern | map/plot-pattern | pie/star-pattern >;  \\n    \\nDefines the characteristics of patterns used in graphs. \\n\\nUsed by: GAREABAR, GCHART, GBARLINE, GCONTOUR, GMAP, GPLOT procedures; SYMBOL \\nstatement; Annotate facility.","attributes":"ForceColor|NumericSuffix"},"COMMENT":{"help":"Specifies the purpose of the statement or program.","attributes":"ForceColor|Global","states":"COMMENT"},"RSUBMIT":{"help":"Syntax: RSUBMIT <options>;  ENDRSUBMIT <CANCEL>;  \\n   RDISPLAY <CONNECTREMOTE=><server-ID;>  \\n   RGET <CONNECTREMOTE=><server-ID>;  \\n   %SYSRPUT macro-variable=value;  \\n   %SYSLPUT macro-variable=value </REMOTE=server-ID>;  \\n   WAITFOR <_ANY_ | _ALL_> task1...taskn <TIMEOUT=seconds>;  \\n   LISTTASK <_ALL_ | task>;  \\n   KILLTASK <_ALL_ | task1...taskn>;  \\n    \\nMarks the beginning of a block of statements that a client session submits to a server\\nsession for execution."},"ENDRSUBMIT":{"help":"Marks the end of a block of statements that a client session submits to a server \\nsession for execution."},"RDISPLAY":{"help":"Syntax: RDISPLAY <<CONNECTREMOTE=>server-ID >;\\n    \\nCreates a Log window to display the lines from the log and an Output window to list \\nthe output generated from the execution of the statements within an asynchronous \\nRSUBMIT block."},"RGET":{"help":"Syntax: RGET <<CONNECTREMOTE=>server-ID>;\\n    \\nRetrieves the log and output that are created by an asynchronous RSUBMIT and merges \\nthem into the Log and Output windows of the client session."},"WAITFOR":{"help":"Syntax: WAITFOR<_ANY_ | _ALL_> taskname <taskname...><TIMEOUT=seconds>;\\n    \\nSuspends execution of the current SAS session until the specified tasks finish \\nexecuting."},"LISTTASK":{"help":"Syntax: LISTTASK <_ALL_|task> ; \\n    \\nLists all active connections or tasks and identifies the execution status of each \\nconnection or task."},"KILLTASK":{"help":"Syntax: KILLTASK _ALL_ |task1...taskn ;\\n    \\nFor asynchronous tasks, forces one or more active tasks or server sessions to \\nterminate immediately."},"SIGNON":{"help":"Syntax: SIGNON <options> \\n    \\nInitiates a connection between a client session and a server session."},"SIGNOFF":{"help":"Syntax: SIGNOFF <options> \\n    \\nEnds the connection between a client session and a server session."},"SYSTASK":{"help":"Syntax: SYSTASK COMMAND \\"operating system command\\" \\n  <WAIT | NOWAIT>\\n  <TASKNAME=taskname>\\n  <MNAME=name-var>\\n  <STATUS=stat-var>\\n  <SHELL<=\\"shell-command\\">>;  \\n  SYSTASK LIST <_ALL_ | taskname> <STATE> <STATVAR>;  \\n  SYSTASK KILL taskname <taskname...>;   \\n    \\nExecutes, lists, or terminates asynchronous tasks."},"X":{"help":"Syntax: X <\'command \'>; \\n    \\nEnters operating environment mode or allows you to submit a Windows command without ending\\nyour SAS session."},"RESETLINE":{"help":"RESETLINE; \\n    \\nRestarts the program line numbers in the SAS log to 1."},"CAS":{"help":"Syntax: CAS session-reference-name options;\\nwhere:\\n\\nsession-reference-name is a valid SAS name that is less than 256 characters.\\n\\nThe CAS statement creates, disconnects or terminates a connection from a SAS client to Cloud Analytic Services (CAS)."},"CASLIB":{"help":"Syntax: CASLIB caslib-reference-name SESSREF=session-reference  \\n    < LIST | DROP > <PATH=directory-path | DATASOURCE=\\"param1=\'value\' param2=\'value\'\\">\\n    <DESCRIPTION=\\"description\\"> <SUBDIRS> <SESSION | LOCAL | GLOBAL> <NOTACTIVE>;\\n\\nwhere:\\n\\ncaslib-reference-name\\n  specifies the name of the caslib. _ALL_ is a valid name with the LIST or DROP options. \\n  The length can be up to 256 characters.\\n\\nThe CASLIB statement is used to manage Cloud Analytic Services (CAS) libraries (caslib) in your CAS session. "},"NOTE":{"help":"Syntax: TITLE<n> <ods-format-options><\'text\' | \\"text\\">; \\n    \\nSpecifies title lines for SAS output.","attributes":"ForceColor|Global|NumericSuffix"},"ATTRIB":{"help":"Syntax: ATTRIB variable-list(s) attribute-list(s) ; \\n    \\nAssociates a format, informat, label, and/or length with one or more variables."},"FORMAT":{"help":"Associates formats with variables.\\n\\nSyntax:\\n(1) FORMAT variable-1 <... variable-n> <format> <DEFAULT=default-format>;\\n\\n(2) FORMAT variable-1 <... variable-n> format <DEFAULT=default-format>;\\n\\n(3) FORMAT variable-1 <... variable-n> format variable-1 <... variable-n> format;\\n\\nIf you omit DEFAULT=, SAS uses BESTw. as the default numeric format and $w. as the default character format."},"INFORMAT":{"help":"Associates informats with variables.\\n\\nSyntax:\\nINFORMAT variable-1 <... variable-n> <informat>;\\n\\nINFORMAT <variable-1> <... variable-n> <DEFAULT=default-informat>;\\n\\nINFORMAT variable-1 <... variable-n> informat <DEFAULT=default-informat>; "},"LABEL":{"help":"Assigns descriptive labels to variables.\\n\\nSyntax:\\n(1) LABEL variable-1=\'label-1\' ... <variable-n=\'label-n\'>; \\n\\n(2) LABEL variable-1=\' \' ... <variable-n=\' \'>; "},"WHERE":{"help":"Syntax: WHERE where-expression-1 < logical-operator where-expression-n>; \\n    \\nwhere\\n\\nlogical-operator can be AND, AND NOT, OR, or OR NOT. \\n\\nSelects observations from SAS data sets that meet a particular condition."},"ABORT":{"help":"Syntax: ABORT <ABEND | RETURN> <n>; \\n    \\nStops executing the current DATA step, SAS job, or SAS session."},"DECLARE":{"help":"Syntax: DECLARE object variable<(<argument_tag-1: value-1<, ...argument_tag-n: value-n>>)>; \\n    \\nDeclares a DATA step component object; creates an instance of and initializes data \\nfor a DATA step component object.\\n\\n"},"DELETE":{"help":"Stops processing the current observation.\\n\\nSyntax: DELETE; "},"DESCRIBE":{"help":"Syntax: DESCRIBE; \\n    \\nRetrieves source code from a stored compiled DATA step program or a DATA step view."},"ERROR":{"help":"Syntax: ERROR <message>; \\n    \\nSets _ERROR_ to 1 and, optionally, writes a message to the SAS log."},"EXECUTE":{"help":"Syntax: EXECUTE; \\n    \\nExecutes a stored compiled DATA step program."},"LIST":{"help":"Syntax: LIST; \\n    \\nWrites to the SAS log the input data record for the observation that is being processed."},"LOSTCARD":{"help":"Syntax: LOSTCARD; \\n    \\nResynchronizes the input data when SAS encounters a missing or invalid record in data \\nthat has multiple records per observation."},"OUTPUT":{"help":"Syntax: OUTPUT<data-set-name(s)>; \\n    \\nWrites the current observation to a SAS data set."},"PUTLOG":{"help":"Syntax: PUTLOG \'message\'; \\n    \\nWrites a message to the SAS log."},"REDIRECT INPUT":{"help":"Syntax: REDIRECT INPUT old-name-1 = new-name-1<... old-name-n = new-name-n>; \\n    \\nThe REDIRECT statement associates the name of the input data set in the source program \\nwith the name of another SAS data set."},"REDIRECT OUTPUT":{"help":"Syntax: REDIRECT OUTPUT old-name-1 = new-name-1<... old-name-n = new-name-n>; \\n    \\nThe REDIRECT statement associates the name of the output data set with the name of \\nanother SAS data set."},"REMOVE":{"help":"Syntax: REMOVE <data-set-name(s)>; \\n    \\n    \\nDeletes an observation from a SAS data set."},"REPLACE":{"help":"Syntax: REPLACE <data-set-name-1><...data-set-name-n>; \\n    \\nReplaces an observation in the same location."},"STOP":{"help":"Syntax: STOP; \\n    \\nStops execution of the current DATA step."},"CONTINUE":{"help":"Syntax: CONTINUE; \\n    \\nStops processing the current DO-loop iteration and resumes with the next iteration."},"THEN":{"help":"Syntax: IF expression THEN statement; \\n    \\nPart of an (IF expression THEN) statement."},"DO":{"help":"[Iterative] Executes statements between DO and END repetitively based on the value \\nof an index variable.\\n\\nSyntax:\\nDO index-variable=specification-1 <, ... specification-n>;\\n... more SAS statements ...\\nEND; "},"UNTIL":{"help":"DO UNTIL executes statements in a DO loop repetitively until a condition is true.\\n\\nSyntax:\\nDO UNTIL (expression);\\n...more SAS statements...\\nEND; "},"WHILE":{"help":"DO WHILE executes statements repetitively while a condition is true.\\n\\nSyntax:\\nDO WHILE (expression);\\n...more SAS statements...\\nEND; "},"END":{"help":"Ends a DO group or a SELECT group.\\nSyntax: END; "},"GO TO":{"help":"Moves execution immediately to the statement label that is specified.\\n\\nSyntax: GO TO label; "},"GOTO":{"help":"See GO TO statement"},"IF":{"help":"Executes a SAS statement for observations that meet specific conditions.\\n\\nSyntax: IF expression THEN statement;\\n  <ELSE statement;>.\\n\\nSyntax: IF expression; \\n\\n[SUBSETTING] Continues processing only those observations that meet the condition"},"ELSE":{"help":"Used in combination with an IF-THEN statement.      \\n\\nSyntax:\\nIF expression THEN statement;\\n<ELSE statement;> "},"LEAVE":{"help":"Syntax: LEAVE; \\n    \\nStops processing the current loop and resumes with the next statement in sequence."},"LINK":{"help":"Jumps to a statement label.\\n\\nSyntax: LINK label; "},"RETURN":{"help":"Syntax: RETURN; \\n    \\nStops executing statements at the current point in the DATA step and returns to a \\npredetermined point in the step."},"SELECT":{"help":"Executes one of several statements or groups of statements.\\n\\nSyntax:\\nSELECT <(select-expression)>;\\n   WHEN-1 (when-expression-1 <..., when-expression-n>) statement;\\n   <... WHEN-n (when-expression-1 <..., when-expression-n>) statement;>\\n       <OTHERWISE statement;>\\nEND; "},"BY":{"help":"Controls the operation of a SET, MERGE, MODIFY, or UPDATE statement in the DATA step \\nand sets up special grouping variables. \\n\\nSyntax: BY <DESCENDING> variable-1\\n  <... <DESCENDING> variable-n > <NOTSORTED><GROUPFORMAT>; "},"CARDS":{"help":"Syntax: CARDS; \\n    \\nIndicates that data lines follow."},"CARDS4":{"help":"Syntax: CARDS4; \\n    \\nIndicates that data lines that contain semicolons follow."},"DATALINES":{"help":"Syntax: DATALINES; \\n    \\nIndicates that data lines follow."},"DATALINES4":{"help":"Syntax: DATALINES4; \\n    \\nIndicates that data lines that contain semicolons follow."},"FILE":{"help":"Syntax: FILE file-specification <options> <operating-environment-options>; \\n    \\nSpecifies the current output file for PUT statements."},"FILE PRINT ODS":{"help":"Syntax: FILE PRINT ODS <=(ODS-suboption(s))><options> ; \\n    \\nCreates an ODS output object by binding the data component to the table definition \\n(template). Optionally, lists the variables to include in the ODS output and \\nspecifies options that control the way that the variables are formatted."},"INFILE":{"help":"Identifies an external file to read with an INPUT statement.\\n\\nSyntax:\\n(1) INFILE file-specification <options > <operating-environment-options>;\\n\\n(2) INFILE DBMS-specifications; "},"INPUT":{"help":"Describes the arrangement of values in the input data record and assigns input values \\nto the corresponding SAS variables. Column INPUT reads input values from specified \\ncolumns and assigns them to the corresponding SAS variables. Formatted INPUT reads \\ninput values with specified informats and assigns them to the corresponding SAS \\nvariables. List INPUT scans the input data record for input values and assigns them \\nto the corresponding SAS variables. Named INPUT reads data values that appear after \\na variable name that is followed by an equal sign and assigns them to corresponding \\nSAS variables.\\n\\nSyntax:\\n(1) INPUT <specification(s)><@|@@>;\\n\\n(2) [Column] INPUT variable <$> start-column <-- end-column> <.decimals> <@ | @@>;\\n\\n(3) [Formatted] INPUT <pointer-control> variable informat. <@ | @@>;\\n\\n(4) [Formatted] INPUT<pointer-control> (variable-list) (informat-list) <@ | @@>;\\n\\n(5) [Formatted] INPUT <pointer-control> (variable-list) (<n*> informat.) <@ | @@>;\\n\\n(6) [List] INPUT <pointer-control> variable <$> <&> <@ | @@>;\\n\\n(7) [List] INPUT <pointer-control> variable <:|&|~> <informat.> <@ | @@>;\\n\\n(8) [Named] INPUT <pointer-control> variable= <$> <@ | @@>;\\n\\n(9) [Named] INPUT <pointer-control> variable= informat. <@ | @@>; \\n\\n(10)[Named] INPUT variable= <$> start-column <-- end-column> <.decimals> <@ | @@>; "},"MERGE":{"help":"Joins observations from two or more SAS data sets into single observations.\\n\\nSyntax:\\nMERGE SAS-data-set-1 <(data-set-options)>\\n  SAS-data-set-2 <(data-set-options) >\\n  <... SAS-data-set-n<(data-set-options)>>\\n  <END=variable>; "},"MODIFY":{"help":"Replaces, deletes, and appends observations in an existing SAS data set in place; \\ndoes not create an additional copy.\\n\\nSyntax:\\n(1) MODIFY master-data-set <(data-set-option(s))> transaction-data-set <(data-set-option(s))> \\n    <NOBS=variable> <END=variable> <UPDATEMODE=MISSINGCHECK | NOMISSINGCHECK>; \\n    BY by-variable; \\n\\n(2) MODIFY master-data-set <(data-set-option(s))> KEY=index </ UNIQUE> <NOBS=variable> <END=variable> ;\\n\\n(3) MODIFY master-data-set <(data-set-option(s))> <NOBS=variable> POINT=variable;\\n\\n(4) MODIFY master-data-set <(data-set-option(s))> <NOBS=variable> <END=variable>; "},"PUT":{"help":"Writes lines to the SAS log, to the SAS output window, or to an external location that \\nis specified in the most recent FILE statement. Column PUT writes variable values in \\nthe specified columns in the output line, Formatted PUT writes variable values with \\nthe specified format in the output line. List PUT writes variable values and the \\nspecified character strings in the output line. Named PUT writes variable values \\nafter the variable name and an equal sign. ODS PUT writes data values to a special \\nbuffer from which they can be written to the data component and formatted by ODS.\\n\\nSyntax:\\n(1) PUT <specification(s)><_ODS_><@|@@>; \\n(2) [Column PUT] PUT variable start-column <-- end-column> <.decimal-places> <@ | @@>;\\n(3) [Formatted PUT] PUT <pointer-control> variable format. <@ | @@>; \\n(4) [Formatted PUT] PUT <pointer-control> (variable-list) (format-list) <@ | @@>;\\n(5) [List PUT] PUT <pointer-control> variable <@ | @@>; \\n(6) [List PUT] PUT <pointer-control> <n*>\'character-string\' <@ | @@>; \\n(7) [List PUT] PUT <pointer-control> variable <: | ~> format.<@ | @@>; \\n(8) [List PUT] PUT <pointer-control> variable= <format.> <@ | @@>;\\n(9) [List PUT] PUT variable= start-column <-- end-column> <.decimal-places> <@ | @@>; "},"SET":{"help":"Syntax: SET<SAS-data-set(s) <(data-set-options(s) )>> <options>; \\n    \\nReads an observation from one or more SAS data sets."},"UPDATE":{"help":"Updates a master file by applying transactions.\\n\\nSyntax:\\nUPDATE master-data-set<(data-set-options)> transaction-data-set<(data-set-options)>\\n   <END=variable>\\n   <UPDATEMODE=\\n   MISSINGCHECK|NOMISSINGCHECK>;\\n   BY by-variable"},"ARRAY":{"help":"Defines elements of an array.\\n\\nSyntax:\\nARRAY array-name { subscript } <$><length>\\n<array-elements> <(initial-value-list)>; "},"DROP":{"help":"Syntax: DROP variable-list; \\n    \\nExcludes variables from output SAS data sets."},"KEEP":{"help":"Syntax: KEEP variable-list; \\n    \\nIncludes variables in output SAS data sets."},"LENGTH":{"help":"Syntax: LENGTH variable-specification(s)<DEFAULT=n>; \\n    \\nSpecifies the number of bytes for storing variables."},"MISSING":{"help":"Syntax: MISSING character(s);  \\n\\nwhere character is the value in your input data that represents a special missing value. \\n\\nAssigns characters in your input data to represent special missing values for numeric data."},"RENAME":{"help":"Syntax: RENAME old-name-1=new-name-1 ... <old-name-n=new-name-n>; \\n    \\nSpecifies new names for variables in output SAS data sets."},"RETAIN":{"help":"Causes a variable that is created by an INPUT or assignment statement to retain \\nits value from one iteration of the DATA step to the next.\\n\\nSyntax:\\nRETAIN <element-list(s) <initial-value(s) |\\n  (initial-value-1) | (initial-value-list-1) >\\n  < ... element-list-n <initial-value-n |\\n  (initial-value-n ) | (initial-value-list-n)>>>; "},"DISPLAY":{"help":"Syntax: DISPLAY window<.group> <NOINPUT > <BLANK> <BELL > <DELETE>;\\n    \\nDisplays a window that is created with the WINDOW statement."},"WINDOW":{"help":"Creates customized windows for your applications.\\n\\nSyntax:\\n(1) WINDOW window <window-options> field-definition(s);\\n(2) WINDOW window <window-options> group-definition(s); "},"WHEN":{"help":"Syntax: WHEN-1 (when-expression-1 <..., when-expression-n>) statement; \\n    \\nUsed in a SELECT-END group in a DATA step. SELECT groups contain WHEN statements \\nthat identify SAS statements that are executed when a particular condition is \\ntrue. Use at least one WHEN statement in a SELECT group."},"OTHERWISE":{"help":"Syntax: <... WHEN-n (when-expression-1 <..., when-expression-n>) statement;> <OTHERWISE statement;> \\n          \\nUsed with a WHEN statement in a SELECT-END group in a DATA step. An optional OTHERWISE statement \\nspecifies a statement to be executed if no WHEN condition is met."}}}')}}]);